SELECT id, rule_name, buffer_mode, business_code, trading_code, pay_channel,
       subject_code, account_no, debit_credit, status, effective_time, expiration_time,
       create_time, update_time, is_delete, tenant_id
FROM t_buffer_posting_rule
WHERE business_code = #{businessCode}
  AND trading_code = #{tradingCode}
  AND pay_channel = #{payChannel}
  AND is_delete = 0
  AND status = 2
  AND effective_time < #{expirationTime}
  AND expiration_time > #{effectiveTime}
  AND id != #{excludeId}

SELECT id, rule_name, buffer_mode, business_code, trading_code, pay_channel,
       subject_code, account_no, debit_credit, status, effective_time, expiration_time,
       create_time, update_time, is_delete, tenant_id
FROM t_buffer_posting_rule
WHERE business_code = #{businessCode}
  AND trading_code = #{tradingCode}
  AND pay_channel = #{payChannel}
  AND debit_credit = #{debitCredit}
  AND effective_time <= #{accountingDate}
  AND expiration_time >= #{accountingDate}
  AND (subject_code IS NULL OR subject_code = '' OR subject_code = #{subjectCode})
  AND (account_no IS NULL OR account_no = '' OR account_no = #{accountNo})
  AND is_delete = 0
ORDER BY id ASC
LIMIT 1
